Compute each row as the previous weight for the same serial number minus the current weight, using 0 for the first occurrence. Sort by date, then row, so the true previous usage is found even if rows are not perfectly ordered. Write the resulting plain numbers into E4:E16.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def norm_date(d):
    if isinstance(d, datetime):
        return d
    if isinstance(d, date):
        return datetime(d.year, d.month, d.day)
    if isinstance(d, (int, float)):
        try:
            return datetime(1899, 12, 30) + timedelta(days=float(d))
        except Exception:
            return datetime.min
    return datetime.min

def norm_serial(s):
    if s is None:
        return None
    if isinstance(s, str):
        s = s.strip()
        return s if s else None
    return s

def to_number(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return float(x)
    if isinstance(x, (int, float)):
        return float(x)
    try:
        return float(str(x).strip())
    except Exception:
        return None

answer_start = 4
answer_end = 16
data_end = max(ws.max_row, vws.max_row, answer_end)

records = []
for r in range(answer_start, data_end + 1):
    serial = norm_serial(vws.cell(row=r, column=2).value)
    d = vws.cell(row=r, column=3).value
    w = to_number(vws.cell(row=r, column=4).value)

    if serial is None and d is None and w is None:
        continue

    records.append((r, serial, d, w))

records.sort(key=lambda item: (norm_date(item[2]), item[0]))

last_weight = {}
results = {}

for r, serial, d, w in records:
    if serial is None:
        continue

    prev = last_weight.get(serial)
    if prev is None or w is None:
        val = 0.0
    else:
        val = prev - w

    if val == 0:
        val = 0.0

    results[r] = val

    if w is not None:
        last_weight[serial] = w

for r in range(answer_start, answer_end + 1):
    if r in results:
        v = results[r]
        if isinstance(v, float) and v.is_integer():
            v = int(v)
        ws.cell(row=r, column=5).value = v
    else:
        ws.cell(row=r, column=5).value = None

wb.save(OUT)

print("records:", len(records))
for r in sorted(results):
    print(r, results[r])
